Future<Kelas> ambilKelas(int id) async {
  final res = await http.get(Uri.parse(
      'https://api.contoh.id/kelas/$id'));
  if (res.statusCode != 200) {
    throw Exception('Gagal memuat');
  }
  return Kelas.fromJson(jsonDecode(res.body)
      as Map<String, dynamic>);
}

